window.ENT142_INDEX=[{"pt": "Week 1", "l": "week-01.html#s0", "n": "Start here", "t": "How do we turn a social problem into a venture people use?", "x": "Your team turns one real social problem, linked to an SDG, into a social venture with evidence. Topics: Overview of the Course · Course Material · Course Assessment · Revisiting the Design Thinking Process · Recap of the DTP · Step 4: Prototyping · Step 5: Testing. CLO 1 · CLO 3."}, {"pt": "Week 1", "l": "week-01.html#s2", "n": "Design thinking recap", "t": "Recap of the design thinking process", "x": "Design thinking has five steps used in loops: empathize, define, ideate, prototype, test. UAE example: InstaShop's founder found ordering groceries by phone slow, built a mobile-first app in Dubai (2015), and Delivery Hero acquired it in 2020, valued at $360 million."}, {"pt": "Week 1", "l": "week-01.html#s3", "n": "Define your problem", "t": "Activity · Define your problem", "x": "Write your problem as [user] needs [need] because [insight], then turn it into a “How might we…?” question."}, {"pt": "Week 1", "l": "week-01.html#s4", "n": "Step 4 · Prototyping", "t": "Step 4 · Prototyping (preview)", "x": "A prototype is the cheapest thing that lets a user experience your idea. Start low fidelity; Week 5 goes deeper."}, {"pt": "Week 1", "l": "week-01.html#s5", "n": "Step 5 · Testing", "t": "Step 5 · Testing", "x": "Give one task, stay silent, watch, then ask open questions. Never defend the idea."}, {"pt": "Week 1", "l": "week-01.html#s6", "n": "Test exchange", "t": "Activity · Test exchange", "x": "Next week: read Byers et al (2019). Ch. 1; each member brings 3 ideas linked to an SDG. Swap prototypes with the team on your left, test for 8 minutes each, and fill in the feedback grid."}, {"pt": "Week 2", "l": "week-02.html#s0", "n": "Start here", "t": "How do we learn what customers want before time runs out?", "x": "Plan the cheapest experiment that shows whether people want your idea. Topics: Lean Startups · Introduction to Lean Startups · Minimum Viable Product (MVP). CLO 1 · CLO 3."}, {"pt": "Week 2", "l": "week-02.html#s1", "n": "Lean startup", "t": "Introduction to lean startups", "x": "A lean startup tests its guesses with real customers before building, in short Build → Measure → Learn loops (Ries, 2011; Blank, 2013)."}, {"pt": "Week 2", "l": "week-02.html#s2", "n": "MVP", "t": "Minimum Viable Product (MVP)", "x": "An MVP gives the most validated learning with the least effort (Ries, 2011). UAE examples: The Entertainer sold printed two-for-one voucher books before launching its app in 2013; Careem launched in Dubai in 2012 as a corporate car-booking service before serving everyone. Click each MVP type for more cases."}, {"pt": "Week 2", "l": "week-02.html#s3", "n": "Pivot or persevere", "t": "Pivot, iterate or persevere?", "x": "Set a target number before the test, then compare. Try different results."}, {"pt": "Week 2", "l": "week-02.html#s4", "n": "Design your MVP", "t": "Activity · Design your MVP experiment", "x": "Next week: read the UN SDGs, Qian et al., (2024) and Bridge et al 2020 Ch1. Fill in your experiment card."}, {"pt": "Week 3", "l": "week-03.html#s0", "n": "Start here", "t": "How do we turn an idea into something people can experience?", "x": "Make your idea visible, testable and easy to explain. Topics: Prototyping · Prototype Generation Techniques · Initial Prototype Development. CLO 1."}, {"pt": "Week 3", "l": "week-03.html#s1", "n": "What is a prototype?", "t": "A prototype makes an idea visible", "x": "A prototype is a simple representation of your solution to see, explain and test it before full development. Jeff Hawkins tested the PalmPilot with a wooden block and a chopstick."}, {"pt": "Week 3", "l": "week-03.html#s2", "n": "Six techniques", "t": "Prototype generation techniques", "x": "Six techniques: sketch, storyboard, paper, digital, physical, role-play. Click each for an example."}, {"pt": "Week 3", "l": "week-03.html#s3", "n": "Prototype Helper", "t": "Choose your prototype · Prototype Helper", "x": "There is no single right prototype. Choose the fastest, cheapest, easiest one that tests your biggest assumption. Load an example idea, edit it, press Send."}, {"pt": "Week 3", "l": "week-03.html#s4", "n": "Real prototypes", "t": "How real teams prototype and show it", "x": "Watch one video: notice how rough the first prototypes are. Startups demo first: prototype → problem → evidence → next test."}, {"pt": "Week 3", "l": "week-03.html#s5", "n": "3D with Meshy AI", "t": "A quick 3D prototype with Meshy AI", "x": "For a physical product, Meshy AI turns a sketch or a sentence into a 3D model (free plan: 100 credits a month). Press ▶ Play. A model shows the look; only users show if it works."}, {"pt": "Week 3", "l": "week-03.html#s6", "n": "Case: Embrace", "t": "Case · Embrace infant warmer", "x": "Stanford students built a low-cost infant warmer (2007). Observing rural families in Nepal changed the design: they added a home model."}];
